module uart_tx(clk, rst, tx_start, tx_data, tx_serial, tx_busy, tx_done);
  input        clk;
  input        rst;
  input        tx_start;
  input  [7:0] tx_data;
  output reg   tx_serial;
  output reg   tx_busy;
  output reg   tx_done;

  localparam [2:0] ST_IDLE  = 3'b000;
  localparam [2:0] ST_START = 3'b001;
  localparam [2:0] ST_DATA  = 3'b010;
  localparam [2:0] ST_STOP  = 3'b011;
  localparam [2:0] ST_DONE  = 3'b100;

  reg [2:0] state;
  reg [7:0] clk_count;
  reg [2:0] bit_index;
  reg [7:0] tx_shift;

  /*
   * This is the terminal-count comparator implemented by the gate netlist.
   * From the reset/reachable counter sequence it fires at clk_count == 8'd86,
   * giving 87 clocks per transmitted UART bit.
   */
  wire baud_tick;
  assign baud_tick = clk_count[7] |
                     (clk_count[6] &
                       (clk_count[5] |
                         (clk_count[4] &
                           (clk_count[3] | (clk_count[2] & clk_count[1])))));

  always @(posedge clk) begin
    if (rst) begin
      state     <= ST_IDLE;
      clk_count <= 8'd0;
      bit_index <= 3'd0;
      tx_busy   <= 1'b0;
      tx_done   <= 1'b0;
      tx_serial <= 1'b1;
    end else begin
      /*
       * Baud counter: active during START/DATA/STOP, cleared on each bit
       * boundary, held in the one-cycle DONE state.
       */
      if (state[2]) begin
        clk_count <= clk_count;
      end else if ((state == ST_START) || (state == ST_DATA) || (state == ST_STOP)) begin
        if (baud_tick)
          clk_count <= 8'd0;
        else
          clk_count <= clk_count + 8'd1;
      end else begin
        clk_count <= 8'd0;
      end

      /*
       * Transmit shift/data holding register.  The netlist does not shift it;
       * data bits are selected by bit_index.
       */
      if ((state == ST_IDLE) && tx_start)
        tx_shift <= tx_data;

      /*
       * Bit index counts data bits 0 through 7, advancing only at the data-bit
       * baud boundary.
       */
      if (state == ST_DATA) begin
        if (baud_tick) begin
          if (bit_index == 3'd7)
            bit_index <= 3'd0;
          else
            bit_index <= bit_index + 3'd1;
        end
      end else if (state == ST_IDLE) begin
        bit_index <= 3'd0;
      end

      /*
       * UART line generation.
       * IDLE/STOP are high, START is low, DATA sends LSB first.
       */
      case (state)
        ST_IDLE:  tx_serial <= 1'b1;
        ST_START: tx_serial <= 1'b0;
        ST_DATA:  tx_serial <= tx_shift[bit_index];
        ST_STOP:  tx_serial <= 1'b1;
        ST_DONE:  tx_serial <= tx_serial;
        default:  tx_serial <= 1'b0;
      endcase

      /*
       * Busy flag and done pulse.
       */
      tx_done <= (state == ST_STOP) && baud_tick;

      if ((state == ST_IDLE) && tx_start)
        tx_busy <= 1'b1;
      else if ((state == ST_STOP) && baud_tick)
        tx_busy <= 1'b0;
      else if (state == ST_IDLE)
        tx_busy <= 1'b0;
      else if (state != ST_DONE)
        tx_busy <= 1'b1;

      /*
       * Main transmitter state machine.
       */
      case (state)
        ST_IDLE: begin
          if (tx_start)
            state <= ST_START;
          else
            state <= ST_IDLE;
        end

        ST_START: begin
          if (baud_tick)
            state <= ST_DATA;
          else
            state <= ST_START;
        end

        ST_DATA: begin
          if (baud_tick && (bit_index == 3'd7))
            state <= ST_STOP;
          else
            state <= ST_DATA;
        end

        ST_STOP: begin
          if (baud_tick)
            state <= ST_DONE;
          else
            state <= ST_STOP;
        end

        ST_DONE: begin
          state <= ST_IDLE;
        end

        default: begin
          state <= ST_IDLE;
        end
      endcase
    end
  end

endmodule

